namespace Aurora {
public partial class MainWindow {
    readonly Dictionary<string,FrameworkElement> pageToolbars=new Dictionary<string,FrameworkElement>();
    ContentControl pageToolbarHost;
    void SetPageToolbar(string id,FrameworkElement toolbar){pageToolbars[id]=toolbar;if(current==id)DisplayPageToolbar(id);}
    void DisplayPageToolbar(string id){if(pageToolbarHost==null)return;pageToolbarHost.Content=null;FrameworkElement toolbar;if(pageToolbars.TryGetValue(id,out toolbar)){var owner=toolbar.Parent as ContentControl;if(owner!=null)owner.Content=null;pageToolbarHost.Content=toolbar;pageToolbarHost.Visibility=Visibility.Visible;}else pageToolbarHost.Visibility=Visibility.Collapsed;}
    TextBox TimeField(Panel parent,string label,string initial){parent.Children.Add(Text(label,12,Muted));var row=new Grid();row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var input=Input(initial);input.MaxLength=5;AutomationProperties.SetName(input,label);AutomationProperties.SetHelpText(input,T("Digite HH:mm ou use o relógio ao lado.","Type HH:mm or use the clock beside it."));row.Children.Add(input);var clock=Button(T("◷ Escolher horário","◷ Choose time"),()=>ChooseTime(input));clock.ToolTip=T("Abrir relógio • Alt+↓ no campo","Open clock • Alt+↓ in the field");Grid.SetColumn(clock,1);row.Children.Add(clock);parent.Children.Add(row);input.PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Down&&(Keyboard.Modifiers&ModifierKeys.Alt)!=0){ChooseTime(input);e.Handled=true;}};return input;}
    void ChooseTime(TextBox input){DateTime parsed;if(!DateTime.TryParseExact(input.Text,"HH:mm",CultureInfo.InvariantCulture,DateTimeStyles.None,out parsed))parsed=DateTime.Today.AddHours(9);var dialog=ToolWindow(T("Escolher horário","Choose time"),420,540);var content=new StackPanel{Margin=new Thickness(18)};var title=Text(T("Horário local • 24 horas","Local time • 24 hours"),20,Accent);content.Children.Add(title);title.MouseLeftButtonDown+=(s,e)=>{if(e.ButtonState==MouseButtonState.Pressed)try{dialog.DragMove();}catch{}};var display=Text("",30,Ink);display.TextAlignment=TextAlignment.Center;content.Children.Add(display);var selectors=new Grid();selectors.ColumnDefinitions.Add(new ColumnDefinition());selectors.ColumnDefinitions.Add(new ColumnDefinition());ComboBox hours=new ComboBox{Margin=new Thickness(0,0,8,8)},minutes=new ComboBox{Margin=new Thickness(0,0,0,8)};for(int i=0;i<24;i++)hours.Items.Add(i.ToString("00"));for(int i=0;i<60;i++)minutes.Items.Add(i.ToString("00"));hours.SelectedIndex=parsed.Hour;minutes.SelectedIndex=parsed.Minute;AutomationProperties.SetName(hours,T("Hora","Hour"));AutomationProperties.SetName(minutes,T("Minuto","Minute"));Grid.SetColumn(minutes,1);selectors.Children.Add(hours);selectors.Children.Add(minutes);content.Children.Add(selectors);var face=new Canvas{Width=260,Height=260,Background=Surface,HorizontalAlignment=HorizontalAlignment.Center};content.Children.Add(face);bool selectingMinutes=false;var mode=Button(T("Selecionar minutos no relógio","Select minutes on the clock"),()=>{});Action draw=()=>{face.Children.Clear();face.Children.Add(new Ellipse{Width=244,Height=244,Stroke=Muted,StrokeThickness=1,Margin=new Thickness(8)});int selected=selectingMinutes?minutes.SelectedIndex:hours.SelectedIndex,total=selectingMinutes?60:24;for(int i=0;i<total;i++){double angle=i*2*Math.PI/total-Math.PI/2;var dot=new Ellipse{Width=3,Height=3,Fill=Muted};Canvas.SetLeft(dot,128+114*Math.Cos(angle));Canvas.SetTop(dot,128+114*Math.Sin(angle));face.Children.Add(dot);if(!selectingMinutes||i%5==0){var number=new TextBlock{Text=i.ToString("00"),Foreground=i==selected?Accent:Ink,FontSize=12,Width=26,TextAlignment=TextAlignment.Center};Canvas.SetLeft(number,117+97*Math.Cos(angle));Canvas.SetTop(number,122+97*Math.Sin(angle));face.Children.Add(number);}}double hand=selected*2*Math.PI/total-Math.PI/2;face.Children.Add(new Line{X1=130,Y1=130,X2=130+75*Math.Cos(hand),Y2=130+75*Math.Sin(hand),Stroke=Accent,StrokeThickness=3});var center=new Ellipse{Width=9,Height=9,Fill=Accent};Canvas.SetLeft(center,125.5);Canvas.SetTop(center,125.5);face.Children.Add(center);display.Text=hours.SelectedItem+":"+minutes.SelectedItem;mode.Content=selectingMinutes?T("Selecionar horas no relógio","Select hours on the clock"):T("Selecionar minutos no relógio","Select minutes on the clock");};hours.SelectionChanged+=(s,e)=>draw();minutes.SelectionChanged+=(s,e)=>draw();mode.Click+=(s,e)=>{selectingMinutes=!selectingMinutes;draw();};face.MouseLeftButtonDown+=(s,e)=>{var p=e.GetPosition(face);if(Math.Sqrt(Math.Pow(p.X-130,2)+Math.Pow(p.Y-130,2))<25)return;double angle=Math.Atan2(p.Y-130,p.X-130)+Math.PI/2;if(angle<0)angle+=2*Math.PI;int value=(int)Math.Round(angle/(2*Math.PI)*(selectingMinutes?60:24))%(selectingMinutes?60:24);if(selectingMinutes)minutes.SelectedIndex=value;else hours.SelectedIndex=value;draw();};Row(content,mode);Row(content,Button(T("Cancelar","Cancel"),()=>dialog.Close()),Button(T("Usar este horário","Use this time"),()=>{input.Text=hours.SelectedItem+":"+minutes.SelectedItem;dialog.DialogResult=true;}));draw();dialog.Content=WindowFrame(content);if(preview&&timePickerPrepared!=null)timePickerPrepared(dialog);dialog.ShowDialog();}
    Window ToolWindow(string title,double width,double height){var window=new Window{Owner=IsVisible?this:null,Icon=Icon,Title=title,Width=Math.Min(width,Math.Max(280,SystemParameters.WorkArea.Width-30)),Height=Math.Min(height,Math.Max(260,SystemParameters.WorkArea.Height-40)),MinWidth=280,MinHeight=240,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.CanResize,WindowStartupLocation=IsVisible?WindowStartupLocation.CenterOwner:WindowStartupLocation.CenterScreen,Background=Surface,Foreground=Ink,ShowInTaskbar=false};window.PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Escape)window.Close();};return window;}
    Border WindowFrame(UIElement content){return new Border{BorderBrush=Accent,BorderThickness=new Thickness(1),Background=Surface,Child=new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled}};}
    void InstallKeyboardSupport(){PreviewKeyDown+=(s,e)=>{if(e.Key==Key.L&&(Keyboard.Modifiers&ModifierKeys.Control)!=0&&navigationSearch!=null){navigationSearch.Focus();navigationSearch.SelectAll();e.Handled=true;}else if(e.Key==Key.F6){if(navigationSearch!=null&&navigationSearch.IsKeyboardFocusWithin){if(pageToolbarHost!=null&&pageToolbarHost.Visibility==Visibility.Visible)pageToolbarHost.MoveFocus(new TraversalRequest(FocusNavigationDirection.First));else body.MoveFocus(new TraversalRequest(FocusNavigationDirection.First));}else if(navigationSearch!=null)navigationSearch.Focus();e.Handled=true;}};}
    static string ResultSymbol(string value){if(ResultTone.IsFailure(value))return "✕ ";if(System.Text.RegularExpressions.Regex.IsMatch(value??"",@"(?i)^\s*(desativado|disabled|inativo|inactive)\b"))return "○ ";if(System.Text.RegularExpressions.Regex.IsMatch(value??"",@"(?i)cancel|aviso|warning|pendente|pending|indisponível|unavailable"))return "ℹ ";return "✓ ";}
}
public static class DiskManufacturer {
    public static string Support(string manufacturer,string model){string text=((manufacturer??"")+" "+(model??"")).ToUpperInvariant();if(text.Contains("SAMSUNG"))return "https://semiconductor.samsung.com/consumer-storage/support/";if(text.Contains("KINGSTON"))return "https://www.kingston.com/support";if(text.Contains("CRUCIAL"))return "https://www.crucial.com/support";if(text.Contains("SANDISK"))return "https://support-en.sandisk.com/";if(text.Contains("WESTERN DIGITAL")||text.Contains("WDC ")||System.Text.RegularExpressions.Regex.IsMatch(text,@"\bWD[SB0-9]"))return "https://support-en.wd.com/";if(text.Contains("SEAGATE")||System.Text.RegularExpressions.Regex.IsMatch(text,@"\bST\d{3,}"))return "https://www.seagate.com/support/";if(text.Contains("KIOXIA"))return "https://apac.kioxia.com/en-apac/personal/support.html";if(text.Contains("TOSHIBA"))return "https://storage.toshiba.com/consumer-hdd/support";if(text.Contains("ADATA")||text.Contains("XPG"))return "https://www.adata.com/en/support/";if(text.Contains("CORSAIR"))return "https://help.corsair.com/";if(text.Contains("INTEL"))return "https://www.intel.com/content/www/us/en/support/products/80096/memory-and-storage.html";if(text.Contains("SOLIDIGM"))return "https://www.solidigm.com/support.html";if(text.Contains("LEXAR"))return "https://www.lexar.com/support/";if(text.Contains("TEAMGROUP"))return "https://support.teamgroupinc.com/en/support/download.php";return null;}
}
}
